<template><div class="ln-task-row ln-focus-ring" :class="{selected,done}" tabindex="0" role="button" @keydown.enter.prevent="$el.click()" @keydown.space.prevent="$el.click()"><div class="ln-task-row__main"><div class="ln-task-row__meta"><span>{{reqNo}}</span></div><strong :title="title">{{title}}</strong></div><div class="ln-task-row__type">{{typeLabel}}</div><div><LnBadge :tone="priorityTone">{{priority}}</LnBadge></div><div><LnBadge :tone="statusTone" dot>{{statusLabel}}</LnBadge></div><div class="ln-task-row__action">{{actionLabel}}</div><time :class="{urgent}">{{updatedAt}}</time><div class="ln-task-row__actions" @click.stop><slot name="actions"/></div></div></template>
<script setup lang="ts">
import{computed}from'vue';import LnBadge from'./LnBadge.vue'
const props=withDefaults(defineProps<{reqNo:string;title:string;typeLabel:string;priority?:string;statusLabel:string;statusTone?:'neutral'|'accent'|'success'|'warning'|'danger';actionLabel:string;updatedAt:string;urgent?:boolean;selected?:boolean;done?:boolean}>(),{priority:'P2',statusTone:'neutral'})
const priorityTone=computed<'neutral'|'accent'|'warning'|'danger'>(()=>props.priority==='P0'?'danger':props.priority==='P1'?'warning':props.priority==='P2'?'accent':'neutral')
</script>
<style scoped lang="scss">.ln-task-row{min-height:62px;padding:9px 14px;display:grid;grid-template-columns:minmax(240px,2fr) 82px 72px 104px minmax(104px,1fr) 98px minmax(112px,auto);align-items:center;gap:10px;border-bottom:1px solid var(--ln-border);background:var(--ln-surface);color:var(--ln-text);font:13px var(--ln-font);cursor:pointer;transition:background var(--ln-fast);&:hover{background:var(--ln-surface-hover)}&.selected{background:var(--ln-accent-soft);box-shadow:inset 2px 0 var(--ln-accent)}&.done{opacity:.82}}.ln-task-row__main{min-width:0;display:grid;gap:5px;strong{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:14px;line-height:1.45;font-weight:600}}.ln-task-row__meta{display:flex;align-items:center;gap:5px;color:var(--ln-text-tertiary);font-size:12px}.ln-task-row__type,.ln-task-row__action{min-width:0;overflow:hidden;text-overflow:ellipsis;color:var(--ln-text-secondary);white-space:nowrap}.ln-task-row time{color:var(--ln-text-tertiary);font-size:12px;&.urgent{color:var(--ln-danger);font-weight:600}}.ln-task-row__actions{display:flex;justify-content:flex-end}@media(max-width:1100px){.ln-task-row{grid-template-columns:minmax(220px,2fr) 78px 104px 98px auto}.ln-task-row__type,.ln-task-row__action{display:none}}@media(max-width:720px){.ln-task-row{grid-template-columns:1fr auto}.ln-task-row>div:nth-child(3),.ln-task-row>div:nth-child(4),.ln-task-row time{display:none}}</style>
